import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions with optional limit and before, strips unknown fields, and rejects malformed options', () => {
    const beforeIso = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
    const beforeEpoch = {updatedAt: 1767225600000, sessionId: 'a'.repeat(128)};
    const valid = {
      bare: validateMessage({type: 'list_sessions'}),
      withOptionsAndExtra: validateMessage({
        type: 'list_sessions',
        limit: 0,
        before: {...beforeIso, extra: 'ignored'},
        userId: 'other-user',
      }),
      withEpochCursor: validateMessage({type: 'list_sessions', limit: 25, before: beforeEpoch}),
    };
    const rejected = [
      validateMessage({type: 'list_sessions', limit: '10'}),
      validateMessage({type: 'list_sessions', limit: -1}),
      validateMessage({type: 'list_sessions', limit: 1.5}),
      validateMessage({type: 'list_sessions', before: null}),
      validateMessage({type: 'list_sessions', before: 'not-an-object'}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}),
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      }),
      validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}),
    ].map(outcome => outcome.valid);

    expect({valid, rejected}).toEqual({
      valid: {
        bare: {valid: true, data: {type: 'list_sessions'}},
        withOptionsAndExtra: {valid: true, data: {type: 'list_sessions', limit: 0, before: beforeIso}},
        withEpochCursor: {valid: true, data: {type: 'list_sessions', limit: 25, before: beforeEpoch}},
      },
      rejected: Array(9).fill(false),
    });
  });
});

