7	interface ValidationSuccess {
8	  valid: true;
9	  data: IncomingMessage;
10	}
11	
12	interface ValidationFailure {
13	  valid: false;
14	  error: string;
15	}
16	
17	export type ValidationResult = ValidationSuccess | ValidationFailure;
18	
19	export function validateMessage(payload: unknown): ValidationResult {
20	  if (typeof payload !== 'object' || payload === null) {
21	    return {valid: false, error: 'Message must be an object'};
22	  }
23	
24	  const message = payload as Record<string, unknown>;
25	
26	  if (typeof message.type !== 'string') {
27	    return {valid: false, error: 'Message must have a type field'};
28	  }
29	
30	  if (message.type === 'user_message') return validateUserMessage(message);
31	  if (message.type === 'ping') return validatePingMessage(message);
32	  if (message.type === 'list_sessions') return validateListSessionsMessage(message);
33	  return {valid: false, error: `Unknown message type: ${message.type}`};
34	}
35	
36	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
37	  if (typeof message.content !== 'string') {
38	    return {valid: false, error: 'user_message must have content string'};
39	  }
40	
41	  const trimmed = message.content.trim();
42	
43	  if (trimmed.length === 0) {
44	    return {valid: false, error: 'Message content cannot be empty'};
45	  }
46	
47	  if (message.content.length > MAX_CONTENT_LENGTH) {
48	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
49	  }
50	
51	  return {
52	    valid: true,
53	    data: {
54	      type: 'user_message',
55	      content: message.content,
56	    },
57	  };
58	}
59	
60	function validatePingMessage(message: Record<string, unknown>): ValidationResult {
61	  if (typeof message.timestamp !== 'number') {
62	    return {valid: false, error: 'ping must have timestamp number'};
63	  }
64	
65	  return {
66	    valid: true,
67	    data: {
68	      type: 'ping',
69	      timestamp: message.timestamp,
70	    },
71	  };
72	}
73	
74	function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
75	  if (!isValidOptionalLimit(message.limit)) {
76	    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
77	  }
78	
79	  const cursor = parseOptionalBefore(message.before);
80	  if (cursor === null) {
81	    return {valid: false, error: 'list_sessions before must have a valid updatedAt and sessionId'};
82	  }
83	
84	  return {
85	    valid: true,
86	    data: {
87	      type: 'list_sessions',
88	      ...(message.limit !== undefined ? {limit: message.limit} : {}),
89	      ...(cursor !== undefined ? {before: cursor} : {}),
90	    },
91	  };
92	}
93	
94	function isValidOptionalLimit(limit: unknown): limit is number | undefined {
95	  if (limit === undefined) return true;
96	  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
97	}
98	
99	function parseOptionalBefore(before: unknown): SessionCursor | undefined | null {
100	  if (before === undefined) return undefined;
101	  if (typeof before !== 'object' || before === null) return null;
102	
103	  const candidate = before as Record<string, unknown>;
104	  if (!isValidSessionId(candidate.sessionId) || !isValidCursorTimestamp(candidate.updatedAt)) {
105	    return null;
106	  }
107	
108	  return {
109	    updatedAt: candidate.updatedAt,
110	    sessionId: candidate.sessionId,
111	  };
112	}
113	
114	function isValidSessionId(sessionId: unknown): sessionId is string {
115	  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
116	}
117	
118	function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
119	  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
120	  return Number.isFinite(new Date(updatedAt).getTime());
121	}
