async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await handleListSessions(ws, session, sessionStore, message);
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  message: Extract<import('../../types/messages.js').IncomingMessage, {type: 'list_sessions'}>
): Promise<void> {
  if (!sessionStore.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : String(s.createdAt),
        updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : String(s.updatedAt),
        entryCount: s.entryCount,
      })),
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listFor failed', {sessionId: session.sessionId, userId: session.userId, error: errorMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

